css:
.container {
  width: 100%;
  height: 100%;
  background-color: #f7e5e5;
  background-image: radial-gradient(#f75454 10%, transparent 10%),
    radial-gradient(#f75454 10%, transparent 10%),
    linear-gradient(
      45deg,
      rgba(247, 84, 84, 0.3) 25%,
      transparent 25%,
      transparent 75%,
      rgba(247, 84, 84, 0.3) 75%
    ),
    linear-gradient(
      -45deg,
      rgba(247, 84, 84, 0.3) 25%,
      transparent 25%,
      transparent 75%,
      rgba(247, 84, 84, 0.3) 75%
    );
  background-size:
    100px 100px,
    100px 100px,
    50px 50px,
    50px 50px;
  background-position:
    0 0,
    50px 50px,
    0 0,
    25px 25px;
}
